@@ -214,0 +214,18 @@
+// Store Pointer Volatile Null
+instruct zStorePVolatileNull(indirect mem, immP0 zero, iRegPNoSp tmp, rFlagsReg cr)
+%{
+  predicate(UseZGC && needs_releasing_store(n) && n->as_Store()->barrier_data() != 0);
+  match(Set mem (StoreP mem zero));
+  effect(TEMP tmp, KILL cr);
+
+  ins_cost(125); // TODO: check if this needs to be adjusted.
+  format %{ "mov    $tmp, #0\n\t"
+            "stlr   $tmp, $mem\t# ptr" %}
+  ins_encode %{
+    const Address ref_addr = Address($mem$$Register);
+    z_store_barrier(masm, this, ref_addr, noreg, $tmp$$Register, rscratch2, false /* is_atomic */);
+    __ stlr($tmp$$Register, $mem$$Register);
+  %}
+  ins_pipe(pipe_serial);
+%}
+
